"""Original conceptual checkpoints; these deliberately do not execute learner text."""

MODIFY_CASES = {
    'what-llm': (
        'A prototype always returns a stored greeting. Which change makes its output a next-token distribution? A: return a longer stored greeting; B: compute a context-dependent score for every vocabulary token; C: repeat the input text.',
        'B', 'Replace fixed retrieval with vocabulary scores conditioned on the available context.'),
    'train-infer': (
        'Your loop currently computes predictions and samples a token. Which change turns it into a training update? A: compute target loss, backpropagate, and step an optimizer; B: print the predictions; C: switch the model to evaluation mode.',
        'A', 'Training needs targets, a loss, gradients, and an update to parameters.'),
    'adaptation': (
        'You have a spam classifier but want to train an instruction-following assistant. What should change? A: keep only spam labels and rename the classes; B: change the dataset filename; C: use prompt/response examples and train response continuations.',
        'C', 'Change the supervision from class labels to desired response sequences.'),
    'decoder': (
        'Your attention layer lets a training position read later tokens. Which modification fixes that information leak? A: mask future scores before softmax; B: increase the number of heads; C: shuffle the order of training batches.',
        'A', 'A future-position mask prevents each query from using information unavailable during generation.'),
    'scale-data': (
        'A demo memorizes one paragraph and its report claims general assistant quality. How should you revise the experiment? A: remove validation; B: keep memorization as an integration check and add held-out evaluation against a stronger baseline; C: generate more samples from the same paragraph.',
        'B', 'Change the evidence and the claim: fitting a tiny example checks the mechanism, while held-out tasks evaluate generalization.'),
    'judge-limits': (
        'A dashboard labels a model “high quality” solely because tensor-shape tests pass. Which revision makes its evidence meaningful? A: show only parameter count; B: change the label color; C: separate implementation checks from held-out response evaluation with a stated rubric.',
        'C', 'Report tested implementation behavior separately from evidence about response quality.'),
    'exercise-reference': (
        'A tracker marks the book exercise complete whenever a related lab exercise passes. What should change? A: track lab checks and attempts at original book exercises separately; B: automatically complete every exercise in the chapter; C: remove source references.',
        'A', 'A related lab exercise does not establish that the original book task was attempted or completed.'),
    'gpu-device': (
        'You move the model to an accelerator but leave its input IDs on CPU. Which change repairs the setup? A: change the random seed; B: move input IDs to the same device as the model; C: enlarge the context window.',
        'B', 'Place the operands used together on compatible devices; changing unrelated settings does not repair a device mismatch.'),
    'distributed': (
        'Every worker reads the entire dataset and updates its own model without communicating. How should you change this to synchronized data-parallel training? A: only add more workers; B: only give workers the same seed; C: shard examples between workers and synchronize gradients before updates.',
        'C', 'Data sharding divides the training examples and gradient synchronization coordinates replica updates.'),
}

def quiz(id,title,idea,points,choices,predict,practice,section):
    def exercise(question,answer,explanation):
        return dict(prompt=question,starter='Your answer: ',reference=answer,tests='Conceptual answer: '+answer,hints=[idea,explanation,'Answer with the letter of the best choice.'],problem=dict(title=title,description=[question],signature='Answer with one letter: A, B, or C.',requirements=['Choose the best explanation for this scenario.'],examples=[dict(input='Answer format',output='A, B, or C'),dict(input='Grading',output='Your choice is compared with the explanation after submission.')],constraints=['Use one answer letter.']))
    l=dict(id=id,title=title,language='python',minutes=5,runtime='llm',mode='conceptual',bookSection=section,
        explanation=[idea,points[0]],learn=dict(diagram=dict(title=title,steps=[dict(label=a,detail=b) for a,b in choices])),example=dict(code='Read the model and diagram on the left. This is a conceptual checkpoint; no code is executed.',notes=[]),prediction=dict(code=predict[0],question=predict[0],expected=predict[1],explanation=predict[2],version='theory-1-'+id),guided=exercise(*MODIFY_CASES[id]),practice=exercise(*practice),sources=[dict(title='Book '+section+' · companion hub',url='https://sebastianraschka.com/llms-from-scratch/')],origin='Supplied · conceptual checkpoint',validated=True)
    assert len({l["prediction"]["question"],l["guided"]["prompt"],l["practice"]["prompt"]}) == 3, id + ": duplicate stage question"
    LESSONS.append(l);CURRENT['conceptIds'].append(id)

group('model-map','00 · The LLM building map','1.1–1.7','Distinguish architecture, training, adaptation, and inference before coding.')
quiz('what-llm','What makes this a language model?','A language model assigns probabilities to token sequences; a GPT predicts the next token from its preceding context.',['Parameters are learned numerical weights; activations are values computed for a particular input.','A next-token objective can learn patterns useful for several tasks, but coherent output does not establish human-like understanding.'],[('Context','Tokens already available'),('Model','Learned parameters transform the context'),('Distribution','Scores and probabilities for the next token')],('A model receives “The cat” and scores every possible next token. What is it computing? A: a next-token distribution; B: a database lookup guarantee; C: a fixed label from a handwritten rule.','A','It scores candidate continuations conditioned on available context.'),('The same weights process two prompts and produce different internal values. Which changed? A: the vocabulary definition; B: activations; C: all trained parameters.','B','Activations depend on the input; inference does not ordinarily update learned parameters.'),'1.1–1.2')
quiz('train-infer','Training versus inference','Training updates parameters from a loss; inference computes outputs using the current parameters.',['Forward computation appears in both training and inference.','A gradient and an optimizer step distinguish an ordinary training update from generation.'],[('Forward','Compute predictions'),('Loss and gradients','Measure errors and differentiate during training'),('Update','Optimizer changes weights')],('You generate a continuation under no_grad without an optimizer step. A: pretraining; B: inference; C: supervised fine-tuning.','B','The model computes outputs without updating its weights.'),('You compute next-token loss, call backward, and step AdamW on raw text. A: inference; B: dataset tokenization only; C: pretraining.','C','The parameters are updated using the language-model training objective.'),'1.3')
quiz('adaptation','Pretraining and two adaptation paths','Pretraining learns from raw text. Classification fine-tuning learns labels; instruction fine-tuning learns response continuations.',['Raw text provides its own next-token targets by shifting the sequence.','Classification examples pair text with class labels; instruction examples pair prompts with desired responses.'],[('Pretrain','Learn next-token patterns from text'),('Classify','Adapt hidden features to labels'),('Instruct','Adapt generation to prompt/response pairs')],('Your dataset pairs email text with spam/not-spam labels. Which path fits? A: classification fine-tuning; B: instruction-response tuning; C: unsupervised tokenization.','A','Class labels supervise a classification head and possibly selected base layers.'),('Your records contain a task, optional input, and a desired paragraph response. A: binary classification; B: instruction fine-tuning; C: only a vocabulary lookup.','B','The target is a response sequence, not a single class label.'),'1.3, 6.1, 7.1')
quiz('decoder','Why GPT uses causal attention','A decoder-style language model predicts the next token without looking at future tokens in its training input.',['Bidirectional encoders can use surrounding context for representation tasks.','A GPT can process many training positions in parallel while the attention mask prevents each position from seeing its future.'],[('Available prefix','Current and earlier token positions'),('Causal mask','Hide later positions'),('Prediction','Estimate the next token')],('During next-token training a position attends to the true following token. A: harmless extra context; B: leakage that must be masked; C: required for inference.','B','The target would be visible during training but unavailable when generating.'),('All positions run together in a masked forward pass. Does parallel computation violate causality? A: yes, always; B: only if vocabulary is large; C: no, if each position cannot access later positions.','C','The mask controls information flow even when computation is parallel.'),'1.4, 1.6')
quiz('scale-data','Educational scale and useful language quality','A tiny model trained on a tiny corpus can demonstrate the training mechanism without becoming a useful general assistant.',['Dataset quality, diversity, quantity, and evaluation boundaries affect what a model learns.','Loading stronger pretrained weights is a separate step from implementing and testing the architecture.'],[('Tiny implementation','Verify the mechanism'),('Held-out evaluation','Check behavior beyond training examples'),('Pretrained baseline','Start adaptation from learned language patterns')],('A tiny model memorizes one paragraph perfectly. What does this show? A: useful open-domain language quality; B: architecture and optimizer can fit that training example; C: guaranteed instruction following.','B','Memorization is a useful integration check, not evidence of generalization.'),('You want a practical starting point for instruction tuning after building GPT. A: load compatible pretrained weights; B: infer quality from parameter count alone; C: mix evaluation answers into training.','A','Compatible pretrained weights provide a stronger baseline while preserving your implemented architecture.'),'1.5, 1.7')
# Place orientation before the executable path; keep all later concepts in their established order.
GROUPS.insert(0,GROUPS.pop())

group('evaluation-models','20 · Evaluate what you built','7.8–7.9; B–C','Separate implementation checks, held-out quality, and further reading.')
quiz('judge-limits','What an evaluation score can establish','Implementation tests, held-out task evaluation, and human review answer different questions about a model.',['Passing shape and causality tests supports specific implementation behavior.','A model judge can be inconsistent or biased; preserve prompts and responses and inspect examples rather than treating one score as ground truth.'],[('Behavior checks','Shapes, masks, gradients, reload'),('Quality checks','Held-out prompts and labels'),('Review','Inspect mistakes and judge limits')],('A model passes all tensor-shape tests. Which conclusion follows? A: it is a high-quality assistant; B: those tested shapes are correct; C: it has no harmful or incorrect outputs.','B','Implementation tests establish only the behaviors they check.'),('A judge gives one response a high score. Next best step? A: claim universal correctness; B: discard the prompt and keep only the score; C: retain the prompt/response and compare a held-out sample with a clear rubric.','C','Traceable held-out examples and a rubric make the score interpretable.'),'7.8')
quiz('exercise-reference','Use the book as the source map','The original book exercises and further-reading references complement this independently authored course.',['Appendix B supplies further reading; Appendix C supplies exercise solutions.','Attempt an original exercise before checking its solution, and track that work separately from these application tests.'],[('Attempt','Work through a book exercise'),('Check','Compare with the appropriate solution'),('Rebuild','Try the component independently later')],('You passed a Concept Lab exercise. Does that mean the book exercise with a similar topic is completed? A: yes automatically; B: no, record the original exercise separately; C: the source no longer matters.','B','The course and original exercises are different tasks.'),('Where should you look for deeper source material after a component is working? A: Appendix B references; B: only training loss; C: the editor line numbers.','A','Appendix B is the book’s further-reading layer.'),'B–C')

group('device-training','21 · Devices and distributed training','A.9','Understand device placement and distributed training without requiring GPU hardware.')
quiz('gpu-device','CPU and GPU are execution devices','A model and the tensors involved in an operation must be on compatible devices; GPU availability is optional for these tiny labs.',['Check availability before selecting an accelerator; CPU is a valid learning runtime.','Moving a module moves registered parameters and buffers, while input tensors still need explicit device placement.'],[('Choose','Select an available device'),('Move','Move both model state and inputs'),('Run','Compute compatible operations')],('Model weights are on an accelerator and input IDs remain on CPU. A: always valid; B: move inputs to the model device; C: changing the seed fixes it.','B','Operands used together must use compatible devices.'),('Your computer has no supported accelerator. Can you do the small course checks? A: yes, they use tiny CPU inputs; B: no PyTorch operation can run; C: only tokenization is possible.','A','The small lab checks are designed for CPU execution.'),'A.9.1–A.9.2')
quiz('distributed','What distributed data parallelism does','Data-parallel training gives each process a model replica and a different shard of examples, then synchronizes gradients.',['Processes need coordinated initialization, device assignment, and cleanup.','DistributedSampler prevents every process from accidentally consuming the same entire dataset; synchronized gradients keep replicas aligned.'],[('Shard','Each worker gets different examples'),('Compute','Each replica computes local gradients'),('Synchronize','Combine gradients before updates')],('Two workers train on the entire same batch independently and never communicate. Is this synchronized data-parallel training? A: yes; B: only if the seed matches; C: no, gradients must be coordinated.','C','Independent training runs do not synchronize model updates.'),('What is the sampler’s job in data-parallel training? A: assign data shards to workers; B: replace the attention mask; C: choose generated vocabulary tokens.','A','Distributed data sampling controls which training examples each worker sees.'),'A.9.3')
